SELECT ?z ?zname ?type WHERE {
  ?z rdfs:label ?zname .
  FILTER (regex(?zname, "Perimeter_bot_ZN_2|DataCenter_mid_ZN_6"))
  ?z a ?type .
}
LIMIT 50

SELECT ?point ?pclass ?tsid WHERE {
  ?zone a brick:HVAC_Zone ; rdfs:label ?zl .
  FILTER (?zl IN ("Perimeter_bot_ZN_2","DataCenter_mid_ZN_6"))
  ?point brick:hasSubEntity ?zone .
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid }
  ?point a ?pclass .
} LIMIT 100

SELECT ?s ?p ?o WHERE {
  ?s brick:hasSubEntity ?z .
  FILTER (str(?z)="http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z08")
  ?s a ?cls .
  ?s ?p ?o .
} LIMIT 50

SELECT ?s WHERE {
  ?z a brick:HVAC_Zone ; rdfs:label "DataCenter_mid_ZN_6" .
  ?s brick:isPointOf ?z .
} LIMIT 50

SELECT ?z ?zlabel ?point ?tsid WHERE {
  ?z a brick:HVAC_Zone ; rdfs:label ?zlabel .
  FILTER (CONTAINS(?zlabel,"Perimeter_bot_ZN_2") || CONTAINS(?zlabel,"DataCenter_mid_ZN_6"))
  ?point brick:isPointOf ?z .
  ?point a brick:Air_Temperature_Sensor .
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid }
}

SELECT ?z ?zlabel ?point ?pclass ?tsid WHERE {
  ?z a brick:HVAC_Zone ; rdfs:label ?zlabel .
  ?point brick:isPointOf ?z .
  ?point a ?pclass .
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid }
